{"content":"import { Link } from "@tanstack/react-router";
import { AVAILABILITY_LABEL, formatPrice, type Product } from "@/data/catalog";
import { useStore } from "@/lib/store";
import { toast } from "sonner";
import { ProductThumb } from "./ProductThumb";

export function AvailabilityPill({ value }: { value: Product["availability"] }) {
  const tone =
    value === "in-stock"
      ? "bg-success/10 text-success"
      : value === "limited"
        ? "bg-warning/15 text-warning"
        : "bg-muted text-muted-foreground";
  return (
    <span className={`inline-flex rounded-sm px-2 py-0.5 text-xs font-semibold ${tone}`}>
      {AVAILABILITY_LABEL[value]}
    </span>
  );
}

export function ProductCard({ product }: { product: Product }) {
  const { addToCart, addToQuote } = useStore();

  return (
    <article className="flex flex-col rounded-md border border-border bg-card shadow-card transition-shadow hover:shadow-raised">
      <Link
        to="/products/$slug"
        params={{ slug: product.slug }}
        className="block border-b border-border p-4"
      >
        <ProductThumb product={product} className="h-32 w-full" />
      </Link>
      <div className="flex flex-1 flex-col p-4">
        <p className="text-xs font-bold uppercase tracking-wide text-sky">{product.manufacturer}</p>
        <h3 className="mt-1 text-base font-semibold leading-snug text-navy">
          <Link to="/products/$slug" params={{ slug: product.slug }} className="hover:underline">
            {product.name}
          </Link>
        </h3>
        <p className="mt-1 font-mono text-xs text-muted-foreground">
          MFR {product.mfrPartNumber} &middot; PB {product.pickrelSku}
        </p>
        <p className="mt-2 line-clamp-2 text-sm text-muted-foreground">{product.shortDescription}</p>
        <div className="mt-3">
          <AvailabilityPill value={product.availability} />
        </div>
        <div className="mt-4 flex items-end justify-between gap-2 border-t border-border pt-3">
          <p className="font-display text-xl font-bold text-navy">
            {formatPrice(product.price)}
            <span className="ml-1 text-xs font-normal text-muted-foreground">/ {product.uom}</span>
          </p>
        </div>
        <div className="mt-3 flex gap-2">
          <button
            type="button"
            onClick={() => {
              addToCart(product.slug, 1);
              toast.success("Added to cart", { description: product.name });
            }}
            className="flex-1 rounded-md bg-navy px-3 py-2 text-sm font-semibold text-navy-foreground transition-colors hover:bg-navy-muted"
          >
            Add to Cart
          </button>
          <button
            type="button"
            onClick={() => {
              addToQuote(product.slug, 1);
              toast.success("Added to quote list", { description: product.name });
            }}
            className="rounded-md border border-input px-3 py-2 text-sm font-semibold text-navy transition-colors hover:bg-secondary"
          >
            Quote
          </button>
        </div>
      </div>
    </article>
  );
}
